function validarEdad(valor) {
  if (typeof valor !== 'number') throw new TypeError('edad debe ser numérica');
  if (valor < 0 || valor > 130) throw new RangeError('edad fuera de rango');
  return valor;
}

function cargarConfig(texto) {
  try {
    return JSON.parse(texto);
  } catch (error) {
    throw new Error('No se pudo cargar la configuración', { cause: error });
  }
}

const error = new Error('No autorizado');
error.code = 'AUTH_REQUIRED';
throw error;

class DomainError extends Error {
  constructor(code, message, options) {
    super(message, options);
    this.name = 'DomainError';
    this.code = code;
  }
}

function obtenerUsuario(texto) {
  try {
    return JSON.parse(texto);
  } catch (error) {
    const wrapped = new Error('Datos de usuario inválidos', { cause: error });
    wrapped.code = 'INVALID_USER_DATA';
    throw wrapped;
  }
}
